mapper.select:
SELECT c.id, c.product_id as productId, c.product_code as productCode, c.product_name as productName, c.product_spec as productSpec, c.product_color as productColor, c.recipe_code as recipeCode, c.recipe_name as recipeName, c.calc_date as calcDate, c.calc_type as calcType, c.total_cost_latest as totalCostLatest, c.total_cost_avg as totalCostAvg, last_c.total_cost_latest as lastPeriodCost, ROUND(c.total_cost_latest - IFNULL(last_c.total_cost_latest, 0), 6) as changeAmount, CASE WHEN IFNULL(last_c.total_cost_latest, 0) = 0 THEN NULL ELSE ROUND((c.total_cost_latest - last_c.total_cost_latest) / last_c.total_cost_latest * 100, 2) END as changeRate FROM mis_cost_calc c LEFT JOIN mis_cost_calc last_c ON last_c.id = ( SELECT c2.id FROM mis_cost_calc c2 WHERE c2.product_id = c.product_id AND c2.del_flag = '0' AND (c2.calc_date < c.calc_date OR (c2.calc_date = c.calc_date AND c2.create_time < c.create_time)) ORDER BY c2.calc_date DESC, c2.create_time DESC LIMIT 1 ) WHERE c.del_flag = '0'
AND c.product_code LIKE CONCAT('%', #{params.productCode}, '%')
AND c.product_name LIKE CONCAT('%', #{params.productName}, '%')
AND c.calc_type = #{params.calcType}
AND c.calc_date >= #{params.startDate}
AND c.calc_date <= #{params.endDate}
ORDER BY c.calc_date DESC, c.product_code

SELECT c.id, c.product_id as productId, c.product_code as productCode, c.product_name as productName, c.product_spec as productSpec, c.product_color as productColor, c.recipe_code as recipeCode, c.recipe_name as recipeName, c.calc_date as calcDate, c.calc_type as calcType, c.total_cost_latest as totalCostLatest, c.total_cost_avg as totalCostAvg, last_c.total_cost_latest as lastPeriodCost, ROUND(c.total_cost_latest - IFNULL(last_c.total_cost_latest, 0), 6) as changeAmount, CASE WHEN IFNULL(last_c.total_cost_latest, 0) = 0 THEN NULL ELSE ROUND((c.total_cost_latest - last_c.total_cost_latest) / last_c.total_cost_latest * 100, 2) END as changeRate FROM mis_cost_calc c LEFT JOIN mis_cost_calc last_c ON last_c.id = ( SELECT c2.id FROM mis_cost_calc c2 WHERE c2.product_id = c.product_id AND c2.del_flag = '0' AND (c2.calc_date < c.calc_date OR (c2.calc_date = c.calc_date AND c2.create_time < c.create_time)) ORDER BY c2.calc_date DESC, c2.create_time DESC LIMIT 1 ) WHERE c.del_flag = '0'
AND c.product_code LIKE CONCAT('%', #{params.productCode}, '%')
AND c.product_name LIKE CONCAT('%', #{params.productName}, '%')
AND c.calc_type = #{params.calcType}
AND c.calc_date >= #{params.startDate}
AND c.calc_date <= #{params.endDate}
ORDER BY c.calc_date DESC, c.product_code
